 126	const LEGACY_MIGRATION_PROMPTED_KEY = "codepi.legacyMigrationPrompted.v1";
 127	
 128	async function offerLegacyMigration(
 129		context: vscode.ExtensionContext,
 130		canonicalAgentDir: string,
 131		codePiSessionDir: string,
 132	): Promise<void> {
 133		if (context.globalState.get<boolean>(LEGACY_MIGRATION_PROMPTED_KEY)) return;
 134	
 135		const legacyAgentDir = path.join(context.globalStorageUri.fsPath, "agent");
 136		const legacySessionDir = path.join(legacyAgentDir, "sessions");
 137		const detected = detectLegacyConfig(legacyAgentDir);
 138		const hasMissingConfig = Boolean(
 139			detected &&
 140				(["settings", "auth", "models"] as const).some(
 141					(file) =>
 142						detected[file] &&
 143						!fs.existsSync(path.join(canonicalAgentDir, `${file}.json`)),
 144				),
 145		);
 146		const hasLegacySessions =
 147			fs.existsSync(legacySessionDir) &&
 148			fs.statSync(legacySessionDir).isDirectory() &&
 149			fs.readdirSync(legacySessionDir).length > 0 &&
 150			(!fs.existsSync(codePiSessionDir) ||
 151				fs.readdirSync(codePiSessionDir).length === 0);
 152		if (!hasMissingConfig && !hasLegacySessions) {
 153			await context.globalState.update(LEGACY_MIGRATION_PROMPTED_KEY, true);
 154			return;
 155		}
 156	
 157		const choice = await vscode.window.showInformationMessage(
 158			"CodePi found legacy storage/configuration or sessions from an older CodePi version. Migrate missing files from the old CodePi storage into this computer's ~/.pi/agent? CodePi sessions move only within this computer's VS Code storage; remote hosts are not affected, and ~/.pi/agent/sessions is never copied.",
 159			"Migrate now",
 160			"Not now",
 161		);
 162		if (choice !== "Migrate now") return;
 163	
 164		try {
 165			const result = migrateLegacyCodePiStorage(
 166				legacyAgentDir,
 167				canonicalAgentDir,
 168				legacySessionDir,
 169				codePiSessionDir,
 170			);
 171			await context.globalState.update(LEGACY_MIGRATION_PROMPTED_KEY, true);
 172			const copied = [
 173				...result.copiedFiles,
 174				...result.copiedSessions.map((name) => `sessions/${name}`),
 175			];
 176			vscode.window.showInformationMessage(
 177				copied.length > 0
 178					? `CodePi migrated ${copied.join(", ")} from its legacy storage.`
 179					: "CodePi found no additional legacy files to migrate.",
 180			);
 181		} catch (error) {
 182			vscode.window.showErrorMessage(
 183				`CodePi could not migrate legacy storage: ${error instanceof Error ? error.message : String(error)}`,
 184			);
 185		}
 186	}
