 190	export async function activate(context: vscode.ExtensionContext) {
 191		extensionContext = context;
 192	
 193		// pi's InteractiveMode ends every quit path (/quit, Ctrl+C/Ctrl+D, signals)
 194		// with process.exit(). VS Code's extension host already neutralizes
 195		// process.exit (patchProcess in extensionHostProcess.ts — it just logs
 196		// "prevented"), so the host survives but our TUI tab is left open with a
 197		// dead session behind it. Intercept instead: when pi asks to exit, close
 198		// the session panel(s) — /quit or closing the tab are the only sanctioned
 199		// ways to end a session. Per-session targeting uses WebviewPty.quitting
 200		// (set when pi's shutdown calls drainInput).
 201		const baseExit = process.exit.bind(process);
 202		(process as unknown as { exit: (code?: number) => never }).exit = ((
 203			code?: number,
 204		) => {
 205			if (sessions.size === 0) {
 230		// caches, so this must run before ANY pi SDK call.
 231		process.env.TERM_PROGRAM = "vscode";
 232		process.env.COLORTERM = "truecolor";
 233	
 234		// Point pi's config and user-resource storage at the executing computer's
 235		// canonical ~/.pi/agent. Must run before any SDK call — pi reads
 236		// PI_CODING_AGENT_DIR at call time.
 237		const agentDir = getCanonicalAgentDir();
 238		setAgentDir(agentDir);
 239		fs.mkdirSync(agentDir, { recursive: true });
 240	
 241		// Copilot-style pending-edit dot on tabs/Explorer for files awaiting review.
 242		registerPendingReviewDots(extensionContext);
 243	
 244		// Keep CodePi conversations in VS Code storage, separate from Pi's
 245		// canonical ~/.pi/agent resources and sessions.
 246		codePiSessionDir = getCodePiSessionDir(context.globalStorageUri.fsPath);
 247		fs.mkdirSync(codePiSessionDir, { recursive: true });
 248		await offerLegacyMigration(context, agentDir, codePiSessionDir);
 249	
 250		// Register session tree provider
 251		treeProvider = new SessionTreeProvider(codePiSessionDir);
 252		const treeView = vscode.window.createTreeView("codepi.sessionsList", {
 253			treeDataProvider: treeProvider,
 254			showCollapseAll: false,
 255		});
 256		context.subscriptions.push(treeView);
 257	
 258		// Restore TUI tabs that were open before a window reload. VS Code persists
 259		// open webview panels and revives them here; the webview content persisted
 260		// its session id via vscode.setState (see terminal.ts), which arrives as
 261		// `state` below.
 262		context.subscriptions.push(
 263			vscode.window.registerWebviewPanelSerializer("codepi-tui", {
 264				deserializeWebviewPanel: async (panel, state) => {
 265					const sessionId = (state as { sessionId?: string } | undefined)
 266						?.sessionId;
 267					if (!sessionId) {
 268						panel.dispose();
 269						return;
 270					}
 271					try {
 272						const sessionPath = await findSessionPathById(sessionId);
 273						if (!sessionPath) {
 274							// Session deleted since the reload — drop the orphaned tab.
 275							panel.dispose();
 276							return;
 277						}
 278						const pi = await getPi();
 279						const sessionManager = pi.SessionManager.open(
 280							sessionPath,
 281							getCodePiSessionDirForRuntime(),
 282							getWorkspaceRoot(),
 283						);
 284						if (sessionManager.getSessionId() !== sessionId) {
 285							panel.dispose();
 286							return;
 287						}
 288						await setupSessionPanel(
 289							panel,
 290							sessionManager,
 291							sessionId,
 292							sessionPath,
 293						);
 294					} catch (err) {
 295						console.error(
 296							"[CodePi] Failed to restore session",
 297							sessionId,
 298							":",
 299							err,
 300						);
 301						panel.dispose();
 302					}
 303				},
 304			}),
 305		);
 306	
 307		// Settings sidebar tab (toggled with the Sessions tree via codepi.sidebarTab)
 308		context.subscriptions.push(
 309			vscode.window.registerWebviewViewProvider(
 310				SettingsViewProvider.viewType,
 311				new SettingsViewProvider(
 312					context.extensionUri,
 313					() => {
 314						// Settings and bundled-resource toggles apply to new sessions.
 315					},
 316					getCanonicalAgentDir(),
 317					getCodePiSessionDirForRuntime(),
 318				),
 319				{ webviewOptions: { retainContextWhenHidden: true } },
 320			),
 321			vscode.commands.registerCommand("codepi.openSettingsTab", () =>
 322				vscode.commands.executeCommand(
 323					"setContext",
 324					"codepi.sidebarTab",
 325					"settings",
 326				),
 327			),
 328			vscode.commands.registerCommand("codepi.openSessionsTab", () =>
 329				vscode.commands.executeCommand(
 330					"setContext",
 331					"codepi.sidebarTab",
 332					"sessions",
 333				),
 334			),
 335		);
 336		await vscode.commands.executeCommand(
 337			"setContext",
 338			"codepi.sidebarTab",
 339			"sessions",
 340		);
 620		try {
 621			const uri = vscode.Uri.parse(uriStr);
 622			const folder = vscode.workspace.getWorkspaceFolder(uri);
 623			if (folder) {
