     1	/**
     2	 * Pure filesystem core for CodePi's own pi config store.
     3	 * NO vscode imports — unit-testable. The agent directory is redirected via
     4	 * process.env.PI_CODING_AGENT_DIR (pi's own getAgentDir() reads it at call
     5	 * time), so everything pi reads/writes lands in the extension's storage.
     6	 */
     7	import { homedir } from "node:os";
     8	import {
     9		chmodSync,
    10		cpSync,
    11		existsSync,
    12		mkdirSync,
    13		readdirSync,
    14		readFileSync,
    15		renameSync,
    16		statSync,
    17		writeFileSync,
    18	} from "node:fs";
    19	import { dirname, join } from "node:path";
    20	
    21	/** Resolve the canonical Pi config directory for the executing computer. */
    22	export function getCanonicalAgentDir(): string {
    23		return join(homedir(), ".pi", "agent");
    24	}
    25	
    26	/** Resolve CodePi's per-extension session directory below VS Code storage. */
    27	export function getCodePiSessionDir(globalStoragePath: string): string {
    28		return join(globalStoragePath, "sessions");
    29	}
    30	
    31	export interface BundledResourceMetadata {
    32		id: "custom-footer" | "filechanges" | "nebula-pulse";
    33		label: string;
    34		kind: "extension" | "theme";
    35		enabledByDefault: boolean;
    36	}
    37	
    38	export const BUNDLED_RESOURCES: readonly BundledResourceMetadata[] = [
    39		{
    40			id: "custom-footer",
    41			label: "Custom footer",
    42			kind: "extension",
    43			enabledByDefault: true,
    44		},
    45		{
    46			id: "filechanges",
    47			label: "File changes",
    48			kind: "extension",
    49			enabledByDefault: true,
    50		},
    51		{
    52			id: "nebula-pulse",
    53			label: "Nebula Pulse theme",
    54			kind: "theme",
    55			enabledByDefault: true,
    56		},
    57	];
    58	
    59	export interface BundledResourceConfig {
    60		bundledExtensions: {
    61			"custom-footer": boolean;
    62			filechanges: boolean;
    63		};
    64		bundledThemes: {
    65			"nebula-pulse": boolean;
    66		};
    67	}
    68	
    69	function isRecord(value: unknown): value is Record<string, unknown> {
    70		return typeof value === "object" && value !== null && !Array.isArray(value);
    71	}
    72	
    73	/** Read CodePi's bundled-resource toggles without trusting malformed settings. */
    74	export function readBundledResourceConfig(
    75		settings: unknown,
    76	): BundledResourceConfig {
    77		const defaults: BundledResourceConfig = {
    78			bundledExtensions: { "custom-footer": true, filechanges: true },
    79			bundledThemes: { "nebula-pulse": true },
    80		};
    81		if (!isRecord(settings) || !isRecord(settings.codepi)) return defaults;
    82	
    83		const codepi = settings.codepi;
    84		const extensions = isRecord(codepi.bundledExtensions)
    85			? codepi.bundledExtensions
    86			: undefined;
    87		const themes = isRecord(codepi.bundledThemes)
    88			? codepi.bundledThemes
    89			: undefined;
    90		return {
    91			bundledExtensions: {
    92				"custom-footer":
    93					typeof extensions?.["custom-footer"] === "boolean"
    94						? extensions["custom-footer"]
    95						: defaults.bundledExtensions["custom-footer"],
    96				filechanges:
    97					typeof extensions?.filechanges === "boolean"
    98						? extensions.filechanges
    99						: defaults.bundledExtensions.filechanges,
   100			},
   101			bundledThemes: {
   102				"nebula-pulse":
   103					typeof themes?.["nebula-pulse"] === "boolean"
   104						? themes["nebula-pulse"]
   105						: defaults.bundledThemes["nebula-pulse"],
   106			},
   107		};
   108	}
   109	
   110	/** Return the bundled resources enabled by the current CodePi settings. */
   111	export function getEnabledBundledResources(
   112		settings: unknown,
   113	): BundledResourceMetadata[] {
   114		const config = readBundledResourceConfig(settings);
   115		return BUNDLED_RESOURCES.filter((resource) =>
   116			resource.kind === "extension"
   117				? config.bundledExtensions[resource.id as "custom-footer" | "filechanges"]
   118				: config.bundledThemes["nebula-pulse"],
   119		).map((resource) => ({ ...resource }));
