 88		min-height: 26px;
 89		border: 1px solid transparent;
 90		border-radius: 3px;
 91		padding: 4px 10px;
 92		cursor: pointer;
 93		color: var(--vscode-button-foreground);
 94		background: var(--vscode-button-background);
 95		font: inherit;
 96	}
 97	
 98	.settings-button:hover {
 99		background: var(--vscode-button-hoverBackground);
100	}
101	
102	.settings-button:focus-visible,
103	.settings-resource-row input:focus-visible {
104		outline: 1px solid var(--vscode-focusBorder);
105		outline-offset: 2px;
106	}
107	
108	.settings-button-secondary {
109		color: var(--vscode-button-secondaryForeground, var(--vscode-foreground));
110		border-color: var(--vscode-button-border, var(--vscode-panel-border));
111		background: var(--vscode-button-secondaryBackground, transparent);
112	}
113	
114	.settings-button-secondary:hover {
115		background: var(
116			--vscode-button-secondaryHoverBackground,
117			var(--vscode-toolbar-hoverBackground)
118		);
119	}
120	
121	.settings-resource-list,
122	.settings-file-list,
123	.settings-package-list {
124		display: flex;
125		flex-direction: column;
126		gap: 7px;
127	}
128	
129	.settings-resource-row {
130		align-items: flex-start;
131		padding: 8px 0;
132		border-top: 1px solid
133			var(--vscode-panel-border, var(--vscode-editorWidget-border));
134	}
135	
136	.settings-resource-row:first-child {
137		border-top: 0;
138	}
139	
140	.settings-resource-copy,
141	.settings-file-row > div {
142		display: flex;
143		flex-direction: column;
144		gap: 2px;
145		min-width: 0;
146	}
147	
148	.settings-resource-label {
149		font-weight: 600;
150	}
151	
152	.settings-resource-row input {
153		flex: 0 0 auto;
154		width: 14px;
155		height: 14px;
156		accent-color: var(--vscode-focusBorder);
157	}
158	
159	.settings-file-row {
160		align-items: center;
161		padding: 8px 0;
162		border-top: 1px solid
163			var(--vscode-panel-border, var(--vscode-editorWidget-border));
164	}
165	
166	.settings-file-row:first-child {
167		border-top: 0;
168	}
169	
170	.settings-package-missing {
171		display: flex;
172		justify-content: space-between;
173		gap: 8px;
174		overflow-wrap: anywhere;
175		padding: 5px 7px;
176		border-left: 2px solid var(--vscode-editorWarning-foreground, #cca700);
177		color: var(--vscode-descriptionForeground, var(--vscode-foreground));
178		background: var(--vscode-textBlockQuote-background, transparent);
179		font-family: var(--vscode-editor-font-family, monospace);
180		font-size: 11px;
181	}
182	
183	.settings-alert {
184		padding: 7px 9px;
185		border-radius: 3px;
186		line-height: 1.4;
187	}
188	
189	.settings-alert-error {
190		border: 1px solid var(--vscode-inputValidation-errorBorder, #f14c4c);
191		color: var(
192			--vscode-inputValidation-errorForeground,
193			var(--vscode-foreground)
194		);
195		background: var(--vscode-inputValidation-errorBackground, transparent);
196	}
197	
198	.settings-alert-status {
199		border: 1px solid
200			var(--vscode-inputValidation-infoBorder, var(--vscode-focusBorder));
201		background: var(--vscode-inputValidation-infoBackground, transparent);
202	}
203	
204	.settings-footer {
205		padding: 4px 1px 10px;
206	}
207	
208	.settings-loading {
209		justify-content: center;
210		color: var(--vscode-descriptionForeground);
211	}
212	
213	@media (max-width: 360px) {
214		.settings-header,
215		.settings-card-heading,
216		.settings-file-row {
217			align-items: stretch;
218			flex-direction: column;
219		}
220	
221		.settings-button {
222			width: 100%;
223		}
224	}
